return items.map(item => {
  const j = item.json || {};
  const nodeName = $prevNode.name || 'RSS';
  const html = j.content || j.description || '';
  const imgMatch = String(html).match(/<img[^>]+src=[\"']([^\"']+)[\"']/i);
  const image = j.enclosure?.url || (imgMatch ? imgMatch[1] : '');

  // Build a stable key without query strings or tracking parameters.
  function canonicalize(url) {
    if (!url) return '';
    try {
      const u = new URL(url);
      return (u.origin + u.pathname).toLowerCase().replace(/\/+$/, '');
    } catch (e) {
      return String(url).split('?')[0].toLowerCase();
    }
  }
  const rawLink = j.link || j.guid || '';
  const dedupKey = j.guid ? `rss:guid:${j.guid}` : `rss:${canonicalize(rawLink)}`;

  return {
    json: {
      dedup_key: dedupKey,
      source_type: 'rss',
      source_category: nodeName.includes('Google News') ? 'google_news' : 'rss',
      media_type: image ? 'image' : 'text',
      source_name: nodeName.replace(/^RSS - /, ''),
      title: j.title || '',
      summary: j.contentSnippet || j.content || j.description || '',
      content: j.contentSnippet || j.content || j.description || '',
      url: rawLink,
      link: rawLink,
      media_url: image,
      image_url: image,
      thumbnail_url: image,
      published_at: j.isoDate || j.pubDate || '',
      author: j.creator || j.author || '',
      raw: j
    }
  };
});

const keywords = [
  'welding','weld','welder','tig','mig','stick',
  'fabrication','metalworking','safety','ppe',
  'mistake','fail','repair','project','robot','laser',
  'pipe','bead','porosity','undercut','stainless','aluminum',
  'meme','funny','shop','workshop','inspection'
];

function containsAny(text, arr) {
  return arr.some(k => text.includes(k));
}

function scoreItem(item) {
  const j = item.json;
  const text = `${j.title || ''} ${j.summary || ''} ${j.content || ''}`.toLowerCase();

  const keyword_hits = keywords.filter(k => text.includes(k)).length;
  const social = Number(j.score || 0) + Number(j.comments || 0);
  const social_boost = Math.min(2.5, Math.log10(social + 1));

  let media_score = 0;
  if (j.media_type === 'youtube') media_score = 8.5;
  else if (j.media_type === 'video') media_score = 9;
  else if (j.media_type === 'gif') media_score = 7.4;
  else if (j.media_type === 'image') media_score = 6.5;
  else media_score = 4;

  let source_boost = 0;
  if (j.source_type === 'youtube') source_boost = 1.4;
  else if (j.source_type === 'rss') source_boost = 1.1;
  else if (j.source_type === 'giphy') source_boost = 0.5;
  else if (j.source_type === 'pexels') source_boost = -1.5;
  else if (j.source_type === 'pixabay') source_boost = -1.5;

  let intent_boost = 0;

  if (containsAny(text, ['mistake','fail','porosity','undercut','repair','inspection'])) {
    intent_boost += 1.5;
  }

  if (containsAny(text, ['safety','ppe','helmet','gloves','fume','fire'])) {
    intent_boost += 1.4;
  }

  if (containsAny(text, ['meme','funny','welder life','shop humor'])) {
    intent_boost += 1.2;
  }

  if (containsAny(text, ['robot','laser','automation','cnc'])) {
    intent_boost += 1.1;
  }

  if (containsAny(text, ['tips','technique','how to','tutorial'])) {
    intent_boost += 1.3;
  }

  const has_media = j.media_url || j.image_url || j.thumbnail_url;

  const final_score = Math.min(
    10,
    media_score * 0.42 +
    keyword_hits * 0.45 +
    social_boost +
    source_boost +
    intent_boost +
    (has_media ? 0.8 : 0)
  );

  return {
    json: {
      ...j,
      keyword_hits,
      social_score: social,
      intent_boost,
      media_rank_score: Number(final_score.toFixed(2))
    }
  };
}

const ranked = items
  .map(scoreItem)
  .filter(item => item.json.media_rank_score >= 7)
  .sort((a, b) => b.json.media_rank_score - a.json.media_rank_score);

const youtube = ranked.filter(i => i.json.media_type === 'youtube');
const gifs = ranked.filter(i => i.json.media_type === 'gif');
const videos = ranked.filter(i => i.json.media_type === 'video');
const images = ranked.filter(i => i.json.media_type === 'image');
const text = ranked.filter(i => !['youtube','gif','video','image'].includes(i.json.media_type));

let selected = [
  ...youtube.slice(0, 1),
  ...gifs.slice(0, 1),
  ...videos.slice(0, 1)
];

const selectedKeys = new Set(
  selected.map(i => i.json.url || i.json.media_url || i.json.title)
);

for (const candidate of [...ranked, ...images, ...text]) {
  if (selected.length >= 2) break;

  const key = candidate.json.url || candidate.json.media_url || candidate.json.title;

  if (!selectedKeys.has(key)) {
    selected.push(candidate);
    selectedKeys.add(key);
  }
}

return selected.slice(0, 2);

return items.map(item => {
  const p = item.json;

  const mediaLabelMap = {
    youtube: 'ویدیو',
    video: 'ویدیو',
    gif: 'GIF',
    image: 'تصویر'
  };
  const mediaLabel = mediaLabelMap[p.media_type] || 'مقاله/خبر';

  const prompt = `تو کیوریتور یک کانال تلگرام فارسی برای جامعه جهانی جوشکاری هستی. این محتوا رسانه‌ای است و باید برای جوشکارها جذاب، کاربردی یا آموزشی باشد.

