function escapeTelegramHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

return items.map((item, i) => {
  const original = $('Final Safety Limit - Max 2 Before OpenAI').all()[i]?.json || {};
  const raw = item.json.choices?.[0]?.message?.content || '';

  let parsed;
  try {
    parsed = JSON.parse(raw.replace(/```json|```/g, '').trim());
  } catch (error) {
    parsed = { publish: false, overall_score: 0, telegram_text: '' };
  }

  const cleanedText = String(parsed.telegram_text || '')
    .replace(/منبع[:：]?\s*\(?https?:\/\/[^\s)]+\)?/gi, '')
    .replace(/https?:\/\/\S+/g, '')
    .trim();

  return {
    json: {
      ...original,
      ...parsed,
      telegram_text: escapeTelegramHtml(cleanedText).slice(0, 950)
    }
  };
});

