function safeHttpUrl(value) {
  try {
    const url = new URL(String(value || ''));
    return ['http:', 'https:'].includes(url.protocol) ? url.href : '';
  } catch (error) {
    return '';
  }
}

function escapeHtmlAttribute(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

return items.map(item => {
  const source = safeHttpUrl(item.json.link || item.json.url || item.json.media_url);
  const sourceLine = source
    ? `\n🌐 <a href="${escapeHtmlAttribute(source)}">منبع</a>`
    : '';

  item.json.telegram_text += `

************
📢 <a href="https://t.me/Welding_News_FA">Welding News FA</a>${sourceLine}`;
  return item;
});

// Read-only filter. Publication records are written only after Telegram confirms delivery.
const historyRows = $('Read Published History').all();
const seen = new Set(historyRows.map(r => r.json.dedup_key).filter(Boolean));

const fresh = [];
for (const item of items) {
  const key = item.json.dedup_key;
  if (!key) continue;
  if (!seen.has(key)) {
    fresh.push(item);
  }
}
return fresh;

const topics = [
  "TIG welding",
  "MIG welding",
  "Stick welding",
  "Pipe welding",
  "Laser welding",
  "Robotic welding",
  "Fabrication",
  "Workshop",
  "Welder",
  "Metalworking",
  "Aluminum welding",
  "Stainless welding",
  "Welding safety",
  "Welding inspection",
  "Repair welding"
];

const intents = [
  "tips",
  "mistakes",
  "fail",
  "repair",
  "project",
  "technique",
  "tutorial",
  "review",
  "comparison",
  "challenge",
  "funny",
  "amazing",
  "beginner",
  "professional"
];

const modifiers = [
  "",
  "",
  "",
  "2026",
  "shorts",
  "viral",
  "real workshop",
  "factory",
  "field",
  "industrial"
];

function random(arr) {
  return arr[Math.floor(Math.random() * arr.length)];
}

const queries = new Set();

while (queries.size < 2) {

  let q = `${random(topics)} ${random(intents)} ${random(modifiers)}`
      .replace(/\s+/g," ")
      .trim();

  queries.add(q);
}

return [...queries].map(q => ({
  json:{
    search_query:q
  }
}));

const ids = [];

for (const item of items) {
  const list = item.json.items || [];

  for (const v of list) {
    const videoId = v.id?.videoId;
    if (!videoId) continue;
    ids.push(videoId);
  }
}

const uniqueIds = [...new Set(ids)].slice(0, 50);

return [
  {
    json: {
      video_ids: uniqueIds.join(',')
    }
  }
];

const out = [];

for (const item of items) {
  const list = item.json.items || [];

  if (!Array.isArray(list) || list.length === 0) {
    continue;
  }

  for (const v of list) {
    const sn = v.snippet || {};
    const stats = v.statistics || {};
    const details = v.contentDetails || {};
    const videoId = v.id || item.json.video_id || '';

    if (!videoId) continue;

    out.push({
      json: {
        dedup_key: `youtube:${videoId}`,
        source_type: 'youtube',
        source_category: 'video',
        media_type: 'youtube',
        source_name: 'YouTube',

        title: sn.title || '',
        summary: sn.description || '',
        content: sn.description || '',

        url: `https://www.youtube.com/watch?v=${videoId}`,
        link: `https://www.youtube.com/watch?v=${videoId}`,
        media_url: `https://www.youtube.com/watch?v=${videoId}`,

        image_url: sn.thumbnails?.high?.url || sn.thumbnails?.medium?.url || sn.thumbnails?.default?.url || '',
        thumbnail_url: sn.thumbnails?.high?.url || sn.thumbnails?.medium?.url || sn.thumbnails?.default?.url || '',

        published_at: sn.publishedAt || '',
        author: sn.channelTitle || '',

        youtube_video_id: videoId,
        youtube_duration: details.duration || '',
        youtube_view_count: Number(stats.viewCount || 0),
        youtube_like_count: Number(stats.likeCount || 0),
        youtube_comment_count: Number(stats.commentCount || 0),

        score:
          Number(stats.viewCount || 0) * 0.001 +
          Number(stats.likeCount || 0) * 0.05 +
          Number(stats.commentCount || 0) * 0.2,

        raw: v
      }
    });
  }
}

return out;
